#define PI 3.142f

float fnSin(float x){
    return sin(x);
}

float fn(float x, float shift){
    return sin(x - PI * shift) - shift + (sin(x * shift) * 0.5) + (sin(x) * 0.2);
}

float lerp(float v1, float v2, float t){
    return ((1.f - t) * v1) + (v2 * t);
}

float wave(float x, float y, float size){
    float a = smoothstep(y, y - size / 2.f - 0.02, x);
    float a1 = smoothstep(y + size / 2.f, y, x);
    float v = smoothstep(0.f, 0.8f, a1 - a);
    return v;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    uv.y -= 0.5;


    vec3 col = vec3(0.f);
    float zoomout = 8.f;
    float size = 0.1;

    float theta = zoomout * PI * uv.x;
    theta -= iTime;

    float y = uv.y * zoomout;

    for(float s = -5.f; s < 5.f; s += 0.5){
        float rV = wave(fn(theta, s), y, size);
        col += vec3(rV);
        //col = vec3(rV);
    }

    uv.y /= 1.1f;
    vec3 lCol = vec3(0.8f, 0.5f, 0.f);
    col = mix(lCol, col * lCol, length(uv));

    fragColor = vec4(col,1.0);
}
